def f(I):
    g=[r[:] for r in I]; H,W=len(g),len(g[0]); changed=True
    while changed:
        changed=False
        # A: horizontal gap fill: run color c on both sides
        for r in range(H):
            for c in range(W):
                if g[r][c]==0:
                    l=c-1
                    while l>=0 and g[r][l]==0: l-=1
                    rt=c+1
                    while rt<W and g[r][rt]==0: rt+=1
                    if l>=0 and rt<W and g[r][l]==g[r][rt]:
                        v=g[r][l]; g[r][c]=v; changed=True
        # B: stub growth: vertical runs >=2 grow up through zeros (iterative)
        for c in range(W):
            for rr in range(H):
                if g[rr][c]:
                    for seg in [[rr]]: pass
        for c in range(W):
            r=H-1
            while r>0 and g[r][c]==g[r-1][c]: r-=1
            top=r+1
            while top>0 and g[top-1][c]==g[top][c] and g[top-1][c]: top-=1
            if r-top>=1 and g[top][c]!=0: continue
            col=g[r][c]
            for cc in range(top,0,-1):
                if g[cc][c]: break
                g[cc][c]=col; changed=True
        # C: bar gap-column growth: filled gap cells grow up
        for r in range(H):
            for c in range(W):
                if g[r][c] and (c>0 and g[r][c-1]==0) or True:
                    pass
        for r in range(H):
            runs=[]; 
            c=0
            while c<W:
                if g[r][c]:
                    cc=g[r][c]; k=c
                    while k<W and g[r][k]==cc: k+=1
                    runs.append((cc,k-c)); c=k
                else: c+=1
            for i in range(len(runs)):
                if runs[i][0]==0: continue
                prev,i=runs[i-1] if i>0 else None,None
                nxt=runs[i+1] if i<len(runs)-1 else None
                if nxt and runs[i][0]==nxt[0] and (i==0 or (prev and prev[0]==0)): 
                    pass
                if nxt and runs[i][0]==nxt[0] and prev and prev[0]!=0:
                    for ch in range(nxt[1]):
                        if g[r][x:=prev and 0] or True:
                            x=i
                    pass
        # simplify: detect gap cells as filled cells where both immediate neighbors in row are same nonzero color
        gaps=set()
        for r in range(H):
            for c in range(W):
                if g[r][c] and (c>0 and g[r][c-1]==g[r][c]) and (c<W-1 and g[r][c+1]==g[r][c]):
                    pass
        # marker approach: redo A marking, then C
        marked=[[False]*W for _ in range(H)]
        for r in range(H):
            for c in range(W):
                if g[r][c]==0:
                    l=c-1
                    while l>=0 and g[r][l]==0: l-=1
                    rt=c+1
                    while rt<W and g[r][rt]==0: rt+=1
                    if l>=0 and rt<W and g[r][l]==g[r][rt]:
                        v=g[r][l]; g[r][c]=v; marked[r][c]=True; changed=True
        for r in range(H):
            for c in range(W):
                if marked[r][c]:
                    col=g[r][c]
                    rr=r-1
                    while rr>=0 and g[rr][c]==0:
                        g[rr][c]=col; changed=True; rr-=1
        # clear marks
    return g

